import "@babylonjs/loaders/glTF";
import "@babylonjs/core/XR/motionController/webXROculusTouchMotionController";

import {
  Engine,
  Scene,
  ArcRotateCamera,
  Vector3,
  Quaternion,
  Ray,
  Color3,
  Color4,
  HemisphericLight,
  MeshBuilder,
  Mesh,
  StandardMaterial,
  TransformNode,
  WebXRDefaultExperience,
  WebXRState,
  WebXRInputSource,
  WebXRMotionControllerManager,
} from "@babylonjs/core";
import packageJson from "../package.json";

const isProductionBuild = (import.meta as ImportMeta & { env?: { PROD?: boolean } }).env?.PROD === true;
const buildInfoEl = document.getElementById("build-info") as HTMLDivElement | null;
const statusEl = document.getElementById("status") as HTMLSpanElement;
const canvas = document.getElementById("render-canvas") as HTMLCanvasElement;

function setStatus(message: string): void {
  if (statusEl) statusEl.textContent = message;
}

function updateBuildInfo(): void {
  if (!buildInfoEl) return;
  const buildNumber = Number((packageJson as { buildNumber?: number }).buildNumber ?? 0);
  const label = `${packageJson.name} v${packageJson.version} · build ${buildNumber} · ${isProductionBuild ? "production" : "development"}`;
  buildInfoEl.textContent = label;
}

WebXRMotionControllerManager.UseOnlineRepository = true;
WebXRMotionControllerManager.PrioritizeOnlineRepository = true;

const engine = new Engine(canvas, true, { adaptToDeviceRatio: true, antialias: true });
const scene = new Scene(engine);
scene.clearColor = new Color4(0, 0, 0, 0);

const camera = new ArcRotateCamera("cam", -Math.PI / 2, Math.PI / 3, 3, Vector3.Zero(), scene);
camera.attachControl(canvas, true);

const light = new HemisphericLight("light", new Vector3(0, 1, 0), scene);
light.intensity = 0.9;

const sceneRoot = new TransformNode("sceneRoot", scene);
const placedBoxes: Mesh[] = [];
let grabbedBox: Mesh | null = null;
let grabbedBoxOffset = Vector3.Zero();
let activeGrabController: WebXRInputSource | null = null;
let pointerBeam: Mesh | null = null;
const xrInputSources: WebXRInputSource[] = [];

function ensurePointerBeam(): Mesh {
  if (pointerBeam) return pointerBeam;

  const beam = MeshBuilder.CreateCylinder("pointerBeam", { height: 1.5, diameterTop: 0.002, diameterBottom: 0.002, tessellation: 8 }, scene);
  beam.isPickable = false;
  beam.parent = sceneRoot;
  beam.setEnabled(false);

  const material = new StandardMaterial("pointerBeamMat", scene);
  material.emissiveColor = new Color3(0.4, 0.9, 1.0);
  material.diffuseColor = new Color3(0.1, 0.25, 0.35);
  material.alpha = 0.85;
  beam.material = material;

  pointerBeam = beam;
  return beam;
}

function addBox(position: Vector3): Mesh {
  const size = 0.08;
  const mesh = MeshBuilder.CreateBox(`box_${placedBoxes.length}`, { size }, scene);
  mesh.position.copyFrom(position);
  mesh.rotationQuaternion = Quaternion.Identity();
  mesh.parent = sceneRoot;
  mesh.computeWorldMatrix(true);

  const material = new StandardMaterial(`boxMat_${placedBoxes.length}`, scene);
  material.diffuseColor = Color3.FromHSV((placedBoxes.length * 47) % 360, 0.85, 0.95);
  material.emissiveColor = new Color3(0.094, 0.094, 0.094);
  mesh.material = material;

  placedBoxes.push(mesh);
  return mesh;
}

function clearBoxes(): void {
  for (const mesh of placedBoxes.splice(0)) {
    mesh.dispose();
  }
  grabbedBox = null;
  activeGrabController = null;
  setStatus("🧹 Cleared all boxes");
}

function removeBox(mesh: Mesh): void {
  const index = placedBoxes.indexOf(mesh);
  if (index >= 0) {
    placedBoxes.splice(index, 1);
  }
  mesh.dispose();
}

function findBoxUnderController(source: WebXRInputSource): Mesh | null {
  const pointer = source.pointer ?? source.grip;
  if (!pointer) return null;

  const origin = pointer.absolutePosition?.clone() ?? Vector3.Zero();
  const direction = pointer.getDirection?.(Vector3.Forward()) ?? Vector3.Forward();
  const ray = new Ray(origin, direction);
  const hit = scene.pickWithRay(ray, (mesh) => placedBoxes.includes(mesh as Mesh));
  return hit?.pickedMesh as Mesh | null;
}

function updatePointerBeam(source: WebXRInputSource): void {
  const beam = ensurePointerBeam();
  const pointer = source.pointer ?? source.grip;
  if (!pointer) {
    beam.setEnabled(false);
    return;
  }

  const origin = pointer.absolutePosition?.clone() ?? Vector3.Zero();
  const direction = pointer.getDirection?.(Vector3.Forward()) ?? Vector3.Forward();
  const ray = new Ray(origin, direction);
  const hit = scene.pickWithRay(ray, (mesh) => placedBoxes.includes(mesh as Mesh));

  const targetPoint = hit?.pickedPoint?.clone() ?? origin.add(direction.scale(1.2));
  const startPoint = origin.clone();
  const beamVec = targetPoint.subtract(startPoint);
  const beamLength = Math.max(beamVec.length(), 0.001);

  beam.setEnabled(true);
  beam.position.copyFrom(startPoint.add(beamVec.scale(0.5)));
  beam.scaling.y = beamLength;
  beam.rotationQuaternion = Quaternion.FromEulerAngles(Math.PI / 2, 0, 0);
  beam.lookAt(targetPoint);
}

function deleteBoxAtController(source: WebXRInputSource): void {
  const target = findBoxUnderController(source);
  if (!target) {
    if (placedBoxes.length > 0) {
      const lastBox = placedBoxes[placedBoxes.length - 1];
      removeBox(lastBox);
      setStatus("🗑 Deleted last box");
    } else {
      setStatus("🗑 No boxes to delete");
    }
    return;
  }

  removeBox(target);
  if (grabbedBox === target) {
    grabbedBox = null;
    activeGrabController = null;
  }
  setStatus("🗑 Deleted box");
}

function placeBoxAtController(source: WebXRInputSource): void {
  const posePos = source.grip?.absolutePosition?.clone() ?? source.pointer?.absolutePosition?.clone() ?? Vector3.Zero();
  const position = posePos.add(new Vector3(0, 0.02, 0));
  addBox(position);
  setStatus(`📦 Placed box (${placedBoxes.length})`);
}

function initController(source: WebXRInputSource): void {
  const mc = source.motionController;
  if (!mc) return;

  const triggerComp = mc.getComponent("trigger") ?? mc.getComponent("xr-standard-trigger");
  if (triggerComp) {
    triggerComp.onButtonStateChangedObservable.add(comp => {
      if (comp.pressed) {
        const target = findBoxUnderController(source);
        if (target) {
          grabbedBox = target;
          grabbedBoxOffset = target.position.subtract((source.grip?.absolutePosition?.clone() ?? source.pointer?.absolutePosition?.clone() ?? Vector3.Zero()));
          activeGrabController = source;
          setStatus("🤏 Moving box");
        } else {
          placeBoxAtController(source);
          setStatus("📦 Placed box");
        }
        mc.pulse?.(0.25, 80);
      } else if (grabbedBox && activeGrabController === source) {
        grabbedBox = null;
        activeGrabController = null;
        setStatus("✋ Box dropped");
      }
    });
  }

  const squeezeComp = mc.getComponentOfType("squeeze");
  if (squeezeComp) {
    squeezeComp.onButtonStateChangedObservable.add(comp => {
      if (comp.pressed) {
        clearBoxes();
        mc.pulse?.(0.3, 100);
      }
    });
  }

  const aButton = mc.getComponent("a-button");
  if (aButton) {
    aButton.onButtonStateChangedObservable.add(comp => {
      if (comp.pressed) {
        deleteBoxAtController(source);
        mc.pulse?.(0.2, 70);
      }
    });
  }
}

async function initXR(): Promise<void> {
  setStatus("⏳ Initialising WebXR…");

  const xr = await WebXRDefaultExperience.CreateAsync(scene, {
    disableDefaultUI: true,
    uiOptions: { sessionMode: "immersive-ar" },
    optionalFeatures: true,
  });

  xr.baseExperience.onStateChangedObservable.add(state => {
    if (state === WebXRState.IN_XR) {
      setStatus("🟢 Quest AR ready — Trigger: place/move box • A: delete • Squeeze: clear");
    } else if (state === WebXRState.NOT_IN_XR) {
      setStatus("⬜ Quest AR not active");
    }
  });

  xr.input.onControllerAddedObservable.add(source => {
    xrInputSources.push(source);
    source.onMotionControllerInitObservable.add(() => {
      initController(source);
    });
  });

  xr.input.onControllerRemovedObservable.add(source => {
    const index = xrInputSources.indexOf(source);
    if (index >= 0) xrInputSources.splice(index, 1);
  });

  updateBuildInfo();
}

window.addEventListener("click", () => {
  if (placedBoxes.length === 0) {
    addBox(new Vector3(0, 0.1, 0));
    setStatus("📦 Starter box added");
  }
});

scene.registerBeforeRender(() => {
  for (const source of xrInputSources) {
    updatePointerBeam(source);
  }

  if (grabbedBox && activeGrabController) {
    const posePos = activeGrabController.grip?.absolutePosition?.clone() ?? activeGrabController.pointer?.absolutePosition?.clone() ?? Vector3.Zero();
    const nextPos = posePos.add(grabbedBoxOffset);
    grabbedBox.position.copyFrom(nextPos);
    grabbedBox.computeWorldMatrix(true);
  }
});

engine.runRenderLoop(() => {
  scene.render();
});

window.addEventListener("resize", () => engine.resize());

void initXR().catch(err => {
  console.error(err);
  setStatus("❌ WebXR could not start");
});
